// Generates the coordinator's problem cache (apps/coordinator/problems.autogenerated.js).
// The coordinator image runs this before bundling; the committed file is an
// empty placeholder, without which the coordinator cannot resolve any problem.
import { readdir, writeFile } from "fs/promises"

import { getProblemInfo } from "@easyshell/problems"
import { ProblemInfo, ProblemInfoSchema } from "@easyshell/problems/schema"
import { PROBLEMS_DIR, PROJECT_ROOT } from "@easyshell/utils/build"

const AUTOGENERATED_PROBLEMS_JS_PATH = `${PROJECT_ROOT}/apps/coordinator/problems.autogenerated.js`

async function main() {
  const data: Record<string, { info: ProblemInfo }> = {}
  for (const problem of await readdir(PROBLEMS_DIR)) {
    data[problem] = {
      info: ProblemInfoSchema.parse(await getProblemInfo(problem)),
    }
  }
  if (Object.keys(data).length === 0) throw new Error("No problems found")
  await writeFile(
    AUTOGENERATED_PROBLEMS_JS_PATH,
    `const data = ${JSON.stringify(data)}\nexport default data\n`,
  )
  console.log(
    `Written ${Object.keys(data).length} problems to ${AUTOGENERATED_PROBLEMS_JS_PATH}`,
  )
}

await main()
